function validate([n]) {
  if (!Number.isInteger(n) || n < 1 || n > 1e9) return 'n is a whole number from 1 to 10^9.';
  return null;
}

reference:
function lastRemaining(n) {
  let head = 1;
  let step = 1;
  let remaining = n;
  let fromLeft = true;

  while (remaining > 1) {
    if (fromLeft || remaining % 2 === 1) {
      head += step;
    }
    remaining = Math.floor(remaining / 2);
    step *= 2;
    fromLeft = !fromLeft;
  }
  return head;
}

