function lastRemaining(n) {
  // Small lists are simulated directly; larger ones use the mirror recurrence, whose
  // base cases are the simulation itself.
  if (n <= 2000) {
    let list = Array.from({ length: n }, (_, i) => i + 1);
    let leftToRight = true;
    while (list.length > 1) {
      const order = leftToRight ? list : [...list].reverse();
      const kept = order.filter((_, i) => i % 2 === 1);
      list = leftToRight ? kept : kept.reverse();
      leftToRight = !leftToRight;
    }
    return list[0];
  }
  const half = Math.floor(n / 2);
  return 2 * (half + 1 - lastRemaining(half));
}

