function generate(rand, size) {
  if (size === 'large') {
    const pick = rand();
    if (pick < 0.2) return [2 ** (20 + Math.floor(rand() * 10))];
    if (pick < 0.3) return [1e9 - Math.floor(rand() * 100)];
    return [1 + Math.floor(rand() * 1e9)];
  }
  return [1 + Math.floor(rand() * (rand() < 0.5 ? 20 : 300))];
}
